        "**Weight-for-age below -2 SD is underweight.** [WHO 2006]",
        "**Length or height-for-age below -2 SD is stunting.** [WHO 2006]",
        "**Weight-for-length or height below -2 SD is wasting.** [WHO 2006]",
        "**Below -3 SD is the severe form** of each index. [WHO 2006]",
        "Weight-for-age cannot separate a short well-nourished child from a wasted one - a screening, not a diagnostic index. [WHO 2006]",
