        "Low-osmolarity ORS replaces the loss in the same proportion in which the gut lost it. [WHO/UNICEF 2004]",
        "Coupled sodium-glucose absorption survives even in secretory diarrhoea - the basis of oral rehydration. [WHO 2005]",
        "Risk factors for death: age **under 1 year**, no breastfeeding, malnutrition. [WHO 2005]",
