            "**Drug and dose: amoxicillin 50 mg/kg orally as a single dose 30-60 minutes before the extraction, maximum 2 g** - for a 7-year-old of about 20-22 kg this is 1000-1100 mg, prescribed as 1 g. **One dose, not a course**; if it is forgotten it can still be given up to 2 hours after the procedure.",
