            "**Make the honest point about proportion: day-to-day oral hygiene prevents far more endocarditis than a single prophylactic dose**, because the bacteraemia that causes endocarditis comes mostly from chewing and brushing on decayed teeth. Twice-daily brushing with fluoride toothpaste, six-monthly dental review, no sugary snacks or night-time sweetened drinks, sugar-free medicine syrups where possible, and no piercings or tattoos.",
