            "**Get an ECG and a chest X-ray. Right axis deviation with an rSR pattern in V1 fits a secundum defect; a superior or left axis deviation means a primum defect; an abnormal P wave axis suggests sinus venosus.** The chest film shows right atrial and ventricular enlargement, a prominent main pulmonary artery, pulmonary plethora and a small aortic knuckle.",
