            "**Assess the child, not just the echocardiogram: plot weight, length and head circumference; ask about feed duration, sweating during feeds, tachypnoea, and the number of chest infections in the last 6 months; count the respiratory rate and heart rate; palpate the liver.** Most 6-month-olds with an atrial septal defect are entirely well.",
