            "**Surgical closure - direct suture or a pericardial patch on cardiopulmonary bypass, mortality under 1% - is used for a primum, sinus venosus or coronary sinus defect, for a very large secundum defect or one with deficient rims, and where an associated lesion (a cleft mitral valve, anomalous pulmonary venous drainage) needs repair.** Risks include post-pericardiotomy syndrome, atrial arrhythmia and sinus node injury after sinus venosus repair, and a sternotomy scar.",
