        "This is a textbook Still's murmur: vibratory and musical, grade 2, at the lower left sternal border in a child of 2-7 years, loudest supine and softer on sitting or standing, with a normal second sound, no thrill and normal pulses in an asymptomatic thriving child. It satisfies all seven S's of an innocent murmur - sensitive, short, single, small, soft, sweet and systolic - and needs confident reassurance with the murmur named, not investigation. An echocardiogram is not needed and its main harm is the anxiety and the false label; a small ventricular septal defect would be a loud harsh pansystolic murmur with a thrill. Antibiotic prophylaxis has no place: even a confirmed small ventricular septal defect no longer qualifies under AHA or ESC. Activity restriction and cardiac non-disease do measurable harm to a child's development. An ECG and chest X-ray in this setting are insensitive, add cost and radiation, and would not change a decision that clinical examination has already made.",
