    "Prevention of Viridans Group Streptococcal Infective Endocarditis: A Scientific Statement From the American Heart Association (Wilson WR et al., Circulation 2021;143:e963-e978) - reaffirms the 2007 highest-risk list and removes clindamycin from the alternative regimens",
