        "It affects about 15-20% of five-year-olds, 10% of seven-year-olds, 5% of ten-year-olds and 1-2% of adolescents; about 15% of affected children become dry spontaneously each year, so treatment is justified by the child's distress rather than by any risk of lifelong persistence.",
