        "A white lesion of the oral mucosa is any patch that appears white because the epithelium is thickened by hyperkeratosis or acanthosis, is oedematous, is covered by a pseudomembrane of fungus and debris, or is necrotic - and the single most useful bedside manoeuvre in sorting them out is to try to wipe or scrape the lesion off with a gauze or spatula.",
        "Lesions that come off (candidal pseudomembrane, milk curds, a chemical or thermal slough) are treated; lesions that do not come off (leukoplakia, lichen planus, oral hairy leukoplakia, chronic hyperplastic candidiasis, carcinoma) are investigated, and in a middle-aged smoker with an adherent white patch, biopsy is mandatory because leukoplakia and chronic hyperplastic candidiasis are both potentially malignant disorders.",
